{"type":"FlowTopic","triggers":[{"type":"Trigger","name":"6598a6849eba4ad0a15634932c17844c","triggerType":"request","applicability":{"type":"Applicability","mode":"script","value":"true"},"id":"6598a6849eba4ad0a15634932c17844c"}],"goals":[{"name":"primary","trigger_id":"6598a6849eba4ad0a15634932c17844c","nodes":[{"type":"StartGoal","goal_id":"primary","greeting_msg":{"type":"String","mode":"string","value":""},"id":"9caca74b3c3b492696f6c67cf0487304","name":"Start","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false},{"type":"TerminateGoal","goal_id":"primary","confirmation_msg":{"type":"String","mode":"string","value":""},"id":"3f1c06fdc6674bf79722cfd400cd59f0","name":"End","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false},{"type":"ScriptedAction","script":"(function execute() {
 /*
 Determining whether there are,
 1. Active incidents opened by the current user
 2. Active Requested items requested for the current user
 and assigning the corresponding script variables.
 */

 // Setting the incident count
 var incidents = new GlideAggregate('incident');
 incidents.addQuery('active', true);
 incidents.addQuery('caller_id', vaInputs.user);
 incidents.addAggregate('COUNT');
 incidents.query();
 var incidentCount = 0;
 if (incidents.next())
 incidentCount = incidents.getAggregate('COUNT');

 vaVars.incident_count = incidentCount;

 // Setting the requested items count
 var reqItems = new GlideAggregate('sc_req_item');
 reqItems.addQuery('active', true);
 reqItems.addQuery('request.requested_for', vaInputs.user);
 reqItems.addAggregate('COUNT');
 reqItems.query();
 var reqItemsCount = 0;
 if (reqItems.next())
 reqItemsCount = reqItems.getAggregate('COUNT');

 vaVars.requested_item_count = reqItemsCount;
})()
","id":"998887d53c974247bf2d2943476e97e2","name":"Check Incidents and Requested Items","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false},{"type":"Decision","name":"Records Decision","branches":[{"type":"Branch","label":"Both Incidents and Requested Items","expression":{"type":"Applicability","mode":"script","value":"(function execute() {
