"},"id":"9a2bcf09a94743cfaf435a633eb21bbd","name":"Requested Items Only","expert_mode":false}],"id":"3e6e426659df4f1fb7ab5e660f2bfa89","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false},{"type":"ReferenceChoiceInputPrompt","mode":"external","id":"d9845d0245604bdc889ee2f91887d37e","name":"Get Record","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false,"variable_id":"ef8c476a54cf4b09aa8f644b28ad8adc","message":{"type":"String","mode":"script","value":"(function execute() {
 if (vaVars.table_name == 'incident') {
 if (parseInt(vaVars.incident_count) > parseInt(vaVars.limit)) 
 return gs.getMessage('You have {0} incidents:', vaVars.incident_count);
 else
 return gs.getMessage('Here are your incidents:');
 }

 if (parseInt(vaVars.requested_item_count) > parseInt(vaVars.limit)) 
 return gs.getMessage('You have {0} requested items:', vaVars.requested_item_count);
 return gs.getMessage('Here are your requested items:');
})()
"},"request_feedback":false,"skippable":{"type":"Applicability","mode":"script","value":"false"},"skipreprompt":{"type":"Applicability","mode":"script","value":"false"},"nlu_entity_binding":{"type":"NLUEntityBinding","allow_text_input":false,"use_confirmation_prompt":false},"expression_mode":"script","script":"(function execute() {
 /*
 1. Query the requested items table and get all the active items requested_for the user
 2. Show the recently updated 5(limit) requested items, apply pagination if there are more than 5.
 */

 var count = 0;
 var options = []; 
 var gr = new GlideRecord(vaVars.table_name);
 gr.addActiveQuery();
 if (vaVars.table_name == 'incident')
 gr.addQuery('caller_id', vaInputs.user);
 else 
 gr.addQuery('request.requested_for', vaInputs.user);

 gr.orderByDesc('sys_updated_on');
 gr.query();

 count = gr.getRowCount();
 vaVars.count = count;
 var cnt = 0;

 while(gr.next()) {
 if (gr.canRead()) {
 if (vaVars.table_name == 'incident')
 options.push({ 'value': gr.getUniqueValue(), 'label': gr.getDisplayValue('short_description') + ' [' + gr.getValue('number') + ']'});
 else
 options.push({ 'value': gr.getUniqueValue(), 'label': gr.getDisplayValue('cat_item') + ' [' + gr.getValue('number') + ']'});
 cnt++;
 } 
 }

 return options;
})()","metadataScript":"","cardName":"","cardFields":[],"no_options_found_message":{"type":"String","mode":"string","value":"gs.getMessageLang("No Records Found", vaContext.getRequesterLang())"},"condition":{"type":"Condition","mode":"external_script","value":"(function execute() {
