 return options;
})()"},"description":"","table":"sc_req_item"},{"type":"ChoiceInputPrompt","expression_mode":"simple","metadataScript":"","cardName":"","cardFields":[],"id":"b996f3b373444cf38b2bec77a4e97fb8","name":"Incident or Requested Item","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false,"variable_id":"351399898a7f4ac5b732ee36477ecdb6","message":{"type":"String","mode":"script","value":"(function execute() {
 var output = '';
 var incidents = '';
 var items = '';

 if (vaVars.incident_count != 1) {
 incidents = gs.getMessage('{0} open incidents',vaVars.incident_count);
 } else {
 incidents = gs.getMessage('{0} open incident', vaVars.incident_count);
 }

 if (vaVars.requested_item_count != 1) {
 items = gs.getMessage('{0} requested items', vaVars.requested_item_count);
 } else {
 items = gs.getMessage('{0} requested item', vaVars.requested_item_count);
 }

 return gs.getMessage('I just checked and you have {0} and {1}. Which status would you like to check?', [incidents,items]);
})()
