 var response = '';
 var gr = new GlideRecordSecure(vaVars.table_name);
 if (gr.get(vaVars.sys_id)) {
 var comment = vaInputs.comment.getValue().trim();
 if (comment) {
 gr.comments = comment;
 gr.update();
 if (vaVars.table_name == 'incident')
 response = gs.getMessage("I've updated the incident.");
 else
 response = gs.getMessage("I've updated the requested item."); 
 } else {
 response = gs.getMessage("OK, no comment will be added.");
 }
 } else
 response = gs.getMessage("I couldn't find the record.");

 return response;
})()"},"secure":false},{"type":"Decision","name":"Decision","branches":[{"type":"Branch","label":"Has Records","expression":{"type":"Applicability","mode":"script","value":"(function execute() {
